package com.nivor.journal.dto;import com.nivor.journal.*;import java.time.*;import java.util.List;public record JournalResponse(Long id,String title,String content,JournalMood mood,List<String> tags,LocalDate entryDate,LocalDateTime createdAt,LocalDateTime updatedAt){public static JournalResponse from(JournalEntry e){return new JournalResponse(e.getId(),e.getTitle(),e.getContent(),e.getMood(),List.copyOf(e.getTags()),e.getEntryDate(),e.getCreatedAt(),e.getUpdatedAt());}}
